// Generates the app's icon set from Lucide (ISC licence): only the glyphs the app uses, as plain data that
// `src/ui/icon.tsx` draws with react-native-svg. Lucide itself is a dev dependency (`lucide-static`); the
// app bundles nothing but the generated file.
//
// Usage: node scripts/build-lucide-icons.mjs [--check]
//   --check   exit 1 when the generated file is out of date, write nothing.
//
// Output (lint-ignored, never hand-edit): src/ui/internal/generated/lucide-icons.ts
//
// To add an icon: add `semanticName: 'lucide-name'` to ICONS below and run the script.
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const outFile = join(root, 'src', 'ui', 'internal', 'generated', 'lucide-icons.ts');

/** Semantic name used by screens → Lucide glyph. */
const ICONS = {
  // chrome
  bell: 'bell',
  bellOff: 'bell-off',
  settings: 'settings',
  menu: 'menu',
  close: 'x',
  back: 'arrow-left',
  forward: 'arrow-right',
  arrowUp: 'arrow-up',
  arrowDown: 'arrow-down',
  chevronDown: 'chevron-down',
  chevronUp: 'chevron-up',
  chevronLeft: 'chevron-left',
  chevronRight: 'chevron-right',
  check: 'check',
  plus: 'plus',
  minus: 'minus',
  search: 'search',
  more: 'ellipsis',
  moreVertical: 'ellipsis-vertical',
  logout: 'log-out',
  login: 'log-in',
  externalLink: 'external-link',
  filter: 'funnel',
  refresh: 'refresh-cw',
  // content
  home: 'house',
  calendar: 'calendar',
  calendarDays: 'calendar-days',
  calendarCheck: 'calendar-check',
  clock: 'clock',
  copy: 'copy',
  edit: 'pencil',
  trash: 'trash-2',
  file: 'file-text',
  filePlus: 'file-plus',
  folder: 'folder',
  folderOpen: 'folder-open',
  image: 'image',
  camera: 'camera',
  upload: 'upload',
  download: 'download',
  share: 'share',
  paperclip: 'paperclip',
  link: 'link',
  eye: 'eye',
  eyeOff: 'eye-off',
  lock: 'lock',
  key: 'key-round',
  mail: 'mail',
  send: 'send',
  star: 'star',
  award: 'award',
  zap: 'zap',
  target: 'target',
  list: 'list',
  grid: 'layout-grid',
  hash: 'hash',
  globe: 'globe',
  sun: 'sun',
  moon: 'moon',
  smartphone: 'smartphone',
  wifiOff: 'wifi-off',
  cloudOff: 'cloud-off',
  code: 'code',
  terminal: 'terminal',
  database: 'database',
  activity: 'activity',
  trendingUp: 'trending-up',
  printer: 'printer',
  message: 'message-square',
  sparkles: 'sparkles',
  flame: 'flame',
  history: 'history',
  // people
  user: 'user',
  users: 'users',
  usersGroup: 'book-user',
  userPlus: 'user-plus',
  userCheck: 'user-check',
  idCard: 'id-card',
  // feedback
  info: 'info',
  help: 'circle-question-mark',
  alert: 'triangle-alert',
  alertCircle: 'circle-alert',
  checkCircle: 'circle-check',
  closeCircle: 'circle-x',
  // number statuses
  rotateCcw: 'rotate-ccw',
  circleDashed: 'circle-dashed',
  // sections
  presentation: 'presentation',
  notebookPen: 'notebook-pen',
  playCircle: 'circle-play',
  clipboard: 'clipboard',
  bookOpen: 'book-open',
  book: 'book',
  bookUser: 'book-user',
  layers: 'layers',
  phone: 'phone',
  phoneCall: 'phone-call',
  phoneMissed: 'phone-missed',
  barChart: 'chart-column',
  sliders: 'sliders-horizontal',
};

const iconsDir = join(root, 'node_modules', 'lucide-static', 'icons');
const { version } = JSON.parse(await readFile(join(root, 'node_modules', 'lucide-static', 'package.json'), 'utf8'));
const ALLOWED_TAGS = new Set(['path', 'circle', 'rect', 'line', 'polyline', 'polygon', 'ellipse']);

/** The child shapes of a Lucide svg file as [tag, attributes] (the files are flat: no groups, no nesting). */
async function shapesOf(glyph, name) {
  const svg = await readFile(join(iconsDir, `${glyph}.svg`), 'utf8').catch(() => null);
  if (svg === null) throw new Error(`Lucide has no icon "${glyph}" (for "${name}")`);
  const body = svg.slice(svg.indexOf('>', svg.indexOf('<svg')) + 1, svg.lastIndexOf('</svg>'));
  const shapes = [];
  for (const [, tag, rawAttrs] of body.matchAll(/<([a-z]+)\s([^>]*?)\/>/g)) {
    if (!ALLOWED_TAGS.has(tag)) throw new Error(`Unsupported <${tag}> in "${glyph}"`);
    const attrs = {};
    for (const [, key, value] of rawAttrs.matchAll(/([a-zA-Z-]+)="([^"]*)"/g)) attrs[key] = value;
    shapes.push([tag, attrs]);
  }
  if (shapes.length === 0) throw new Error(`No shapes parsed from "${glyph}"`);
  return shapes;
}

const lines = [];
for (const [name, glyph] of Object.entries(ICONS)) {
  lines.push(`  ${name}: ${JSON.stringify(await shapesOf(glyph, name))},`);
}

const source = `// GENERATED by scripts/build-lucide-icons.mjs from lucide-static ${version} (ISC licence). Do not edit.
// Each icon: a list of [tag, attributes] drawn on a 24 × 24 view box with stroke 2, round caps and joins.
export type IconShape = readonly [tag: 'path' | 'circle' | 'rect' | 'line' | 'polyline' | 'polygon' | 'ellipse', attrs: Readonly<Record<string, string>>];

export const LUCIDE_ICONS = {
${lines.join('\n')}
} as const satisfies Record<string, readonly IconShape[]>;

export type LucideIconName = keyof typeof LUCIDE_ICONS;
`;

if (process.argv.includes('--check')) {
  const current = await readFile(outFile, 'utf8').catch(() => '');
  if (current !== source) {
    console.error('src/ui/internal/generated/lucide-icons.ts is out of date: run node scripts/build-lucide-icons.mjs');
    process.exit(1);
  }
  console.log('lucide icons are up to date');
} else {
  await mkdir(dirname(outFile), { recursive: true });
  await writeFile(outFile, source);
  console.log(`wrote ${Object.keys(ICONS).length} icons to ${outFile}`);
}
